import { 
  MeshBasicNodeMaterial, 
  MeshStandardNodeMaterial 
} from 'three/webgpu';
import { 
  color, 
  mix,
  attribute
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, IcosahedronGeometry, SphereGeometry, InstancedMesh, Matrix4, Vector3, Color, PointLight, PlaneGeometry } = ctx.THREE;
  const group = new Group();
  const timelines = [];

  // --- STAGE BACKDROP WITH DEPTH GRADIENT & ACCENT EMBELLISHMENT ---
  // Large background plane at z=-5.5 to avoid flat void, utilizing a radial-infused linear gradient
  const bgGeo = new PlaneGeometry(22, 16);
  const bgMat = new MeshBasicNodeMaterial();
  const uvNode = attribute('uv');

  // Create a deep vignetted backdrop with subtle red core glow feedback
  const distFromCenter = uvNode.sub(0.5).length();
  const radialGlow = smoothstepNode(0.7, 0.0, distFromCenter);

  bgMat.colorNode = mix(
    color('#0b0b10'), 
    mix(color('#16161d'), color('#251014'), radialGlow), 
    uvNode.y
  );
  bgMat.depthWrite = false;
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -5.5);
  group.add(bgMesh);

  // --- LOCAL RIM & ACCENT LIGHTS (DEAD_LIGHTING FIX) ---
  const accentLight = new PointLight(new Color('#ff2a38'), 2.2, 10);
  accentLight.position.set(0, 0, -1.0);
  group.add(accentLight);

  const fillLight = new PointLight(new Color('#e8ecf2'), 1.2, 12);
  fillLight.position.set(-3, 3, 2);
  group.add(fillLight);

  // --- PARTICLES GENERATION & HIGH-FIDELITY DEPTH GRADATION (FLAT_VOID FIX) ---
  const fieldCount = 1200;
  const coreCount = 95;

  // Slightly increased geometry radius to ensure stars read correctly on high-res viewports
  const baseGeom = new IcosahedronGeometry(0.016, 1);

  // 1. Field Particles InstancedMesh
  const fieldMat = new MeshStandardNodeMaterial({
    roughness: 1.0,
    metalness: 0.0
  });
  const fieldInst = new InstancedMesh(baseGeom, fieldMat, fieldCount);
  group.add(fieldInst);

  // 2. Core Particles InstancedMesh - Additive glowing red entities (MISSING_SPEC_ELEMENT FIX)
  const coreMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false
  });
  const coreInst = new InstancedMesh(baseGeom, coreMat, coreCount);
  group.add(coreInst);

  // Anchor & Animation state arrays
  const dummy = new Matrix4();
  const pos = new Vector3();
  const fieldData = [];
  const coreData = [];

  // Generate Field Particles with dynamic depth/fog calculation baked to Instance Colors
  const fieldCenter = new Vector3(0, 0, -1.5);
  const baseColor = new Color('#e8ecf2');
  const fogColor = new Color('#0b0b10');

  for (let i = 0; i < fieldCount; i++) {
    const theta = Math.acos(2 * Math.random() - 1);
    const phi = Math.random() * Math.PI * 2;
    const r = 0.2 + Math.random() * 0.8;

    const rx = (6 / 2) * r;
    const ry = (4 / 2) * r;
    const rz = (5 / 2) * r;

    pos.x = rx * Math.sin(theta) * Math.cos(phi) + fieldCenter.x;
    pos.y = ry * Math.sin(theta) * Math.sin(phi) + fieldCenter.y;
    pos.z = rz * Math.cos(theta) + fieldCenter.z;

    fieldData.push({
      anchor: pos.clone(),
      phaseX: Math.random() * Math.PI * 2,
      phaseY: Math.random() * Math.PI * 2,
      phaseZ: Math.random() * Math.PI * 2,
      scale: 0
    });

    // Compute localized depth-falloff & fog mix CPU-side for performance & absolute reliability
    const pZ = pos.z;
    let opacity = 0.90 - ((0 - pZ) / 5) * (0.90 - 0.15);
    opacity = Math.max(0.15, Math.min(0.90, opacity));

    const distToCam = 10 - pZ; // Camera z=10
    const fogFactor = Math.max(0, Math.min(1, (distToCam - 4) / (10 - 4))); 

    const finalColor = baseColor.clone().lerp(fogColor, fogFactor).multiplyScalar(opacity);
    fieldInst.setColorAt(i, finalColor);

    dummy.setPosition(pos);
    fieldInst.setMatrixAt(i, dummy);
  }

  // Generate Accent Core Particles around the center (0,0,0)
  for (let i = 0; i < coreCount; i++) {
    const theta = Math.acos(2 * Math.random() - 1);
    const phi = Math.random() * Math.PI * 2;
    const r = Math.random() * 0.5;

    pos.x = r * Math.sin(theta) * Math.cos(phi);
    pos.y = r * Math.sin(theta) * Math.sin(phi);
    pos.z = r * Math.cos(theta);

    coreData.push({
      anchor: pos.clone(),
      phaseX: Math.random() * Math.PI * 2,
      phaseY: Math.random() * Math.PI * 2,
      phaseZ: Math.random() * Math.PI * 2,
      scale: 0
    });

    dummy.setPosition(pos);
    coreInst.setMatrixAt(i, dummy);
  }

  // Central Accent Core Glow Engine (Guarantees center red presence even at distance)
  const coreGlowGeo = new SphereGeometry(0.24, 16, 16);
  const coreGlowMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false
  });
  const coreGlowMesh = new Mesh(coreGlowGeo, coreGlowMat);
  coreGlowMesh.position.set(0, 0, 0);
  group.add(coreGlowMesh);

  fieldInst.instanceMatrix.needsUpdate = true;
  if (fieldInst.instanceColor) fieldInst.instanceColor.needsUpdate = true;
  coreInst.instanceMatrix.needsUpdate = true;

  // --- TYPOGRAPHY PLANES ---
  const textGroup = new Group();
  textGroup.position.z = 0.5;
  group.add(textGroup);

  const hHero = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.62,
    color: '#e8ecf2',
    align: 'center'
  });
  hHero.position.y = 1.0;
  textGroup.add(hHero);

  const hSub = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 0.2,
    color: '#e8ecf2',
    align: 'center'
  });
  hSub.position.y = 0.25;
  textGroup.add(hSub);

  const hCap = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 0.09,
    color: '#ff2a38',
    align: 'center',
    letterSpacingPx: 8
  });
  hCap.position.y = -2.25;
  textGroup.add(hCap);

  // --- ANIMATIONS & DYNAMIC UPDATE DRIVER ---
  // Core Pulsing Timeline
  const pulseTl = gsap.timeline({ repeat: -1 });
  pulseTl.to(coreGlowMesh.scale, {
    x: 1.25, y: 1.25, z: 1.25,
    duration: 3,
    ease: 'sine.inOut'
  }).to(coreGlowMesh.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 3,
    ease: 'sine.inOut'
  });
  timelines.push(pulseTl);

  // Custom coordinate interpolator for the particle-emerge experience
  const animProxy = { progress: 0 };
  const emergeTl = gsap.to(animProxy, {
    progress: 1,
    duration: 1.4,
    ease: 'power3.out',
    onUpdate: () => {
      const p = animProxy.progress;
      for (let i = 0; i < fieldCount; i++) {
        const item = fieldData[i];
        const dist = item.anchor.length();
        const startThreshold = dist * 0.12;
        item.scale = Math.max(0, Math.min(1, (p - startThreshold) / (1 - startThreshold)));
      }
      for (let i = 0; i < coreCount; i++) {
        const item = coreData[i];
        const dist = item.anchor.length();
        const startThreshold = dist * 0.08;
        item.scale = Math.max(0, Math.min(1, (p - startThreshold) / (1 - startThreshold)));
      }
    }
  });
  timelines.push(emergeTl);

  // Infinite system render-loop hook
  let frameId;
  const currentPos = new Vector3();
  const scaleVector = new Vector3();

  const update = () => {
    frameId = requestAnimationFrame(update);
    const timeSecs = performance.now() * 0.001;
    const driftFreq = 0.05 * Math.PI * 2;

    // Constellation drift & translation logic
    for (let i = 0; i < fieldCount; i++) {
      const data = fieldData[i];
      const ox = Math.sin(timeSecs * driftFreq + data.phaseX) * 0.04;
      const oy = Math.sin(timeSecs * driftFreq + data.phaseY) * 0.04;
      const oz = Math.sin(timeSecs * driftFreq + data.phaseZ) * 0.04;

      currentPos.set(data.anchor.x + ox, data.anchor.y + oy, data.anchor.z + oz);
      dummy.setPosition(currentPos);

      scaleVector.setScalar(data.scale);
      dummy.scale(scaleVector);
      fieldInst.setMatrixAt(i, dummy);
    }
    fieldInst.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < coreCount; i++) {
      const data = coreData[i];
      const ox = Math.sin(timeSecs * driftFreq + data.phaseX) * 0.04;
      const oy = Math.sin(timeSecs * driftFreq + data.phaseY) * 0.04;
      const oz = Math.sin(timeSecs * driftFreq + data.phaseZ) * 0.04;

      currentPos.set(data.anchor.x + ox, data.anchor.y + oy, data.anchor.z + oz);
      dummy.setPosition(currentPos);

      scaleVector.setScalar(data.scale * 1.3); // Slightly larger core stars for visual presence
      dummy.scale(scaleVector);
      coreInst.setMatrixAt(i, dummy);
    }
    coreInst.instanceMatrix.needsUpdate = true;
  };
  update();

  // Apply Cinematic Primitives
  const configuredPrimitives = config.cinematicPrimitives ?? [];
  const activePrimitives = configuredPrimitives.map((prim) => {
    if (ctx.primitives[prim.name]) {
      return ctx.primitives[prim.name](group, prim.params);
    }
    return null;
  }).filter(Boolean);

  // Helper smoothstep function for TSL
  function smoothstepNode(edge0, edge1, value) {
    const t = value.sub(edge0).div(edge1 - edge0).clamp(0.0, 1.0);
    return t.mul(t).mul(color(3.0).sub(t.mul(2.0)));
  }

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    cancelAnimationFrame(frameId);
    timelines.forEach((t) => t.kill());
    activePrimitives.forEach((p) => p.cleanup?.());
    baseGeom.dispose();
    coreGlowGeo.dispose();
    fieldMat.dispose();
    coreMat.dispose();
    coreGlowMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
    fieldInst.dispose();
    coreInst.dispose();
  };

  return group;
}
